class LoginPage extends StatefulWidget { const LoginPage({super.key,required this.api,required this.store,required this.onLogin}); final StudentApi api; final SessionStore store; final ValueChanged<String> onLogin; @override State<LoginPage> createState()=>_LoginPageState(); }
