class _DashboardPageState extends State<DashboardPage>{DashboardData? data;String? error;bool loading=true;final examToken=TextEditingController();@override void initState(){super.initState();examToken.text=widget.config.demoExamToken;load();}@override void dispose(){examToken.dispose();super.dispose();}Future<void> load()async{setState((){loading=true;error=null;});try{final d=await widget.api.dashboard(widget.token);if(mounted)setState(()=>data=d);}catch(_){if(mounted)setState(()=>error='دریافت داشبورد انجام نشد.');}finally{if(mounted)setState(()=>loading=false);}}Future<void> logout()async{try{await widget.api.logout(widget.token);}catch(_){ }await widget.store.clear();widget.onLogout();}Future<void> openExam({String? attemptId})async{try{ExamStart start;if(attemptId!=null){start=await widget.api.resumeAttempt(attemptId,widget.token);}else{if(examToken.text.trim().isEmpty)return;start=await widget.api.startExam(examToken.text,widget.token);}if(!mounted)return;if(start.status=='submitted'){Navigator.push(context,MaterialPageRoute(builder:(_)=>ResultPage(api:widget.api,token:widget.token,attemptId:start.attemptId)));}else{await Navigator.push(context,MaterialPageRoute(builder:(_)=>ExamPage(api:widget.api,token:widget.token,attemptId:start.attemptId,title:start.title)));await load();}}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('آزمون در دسترس نیست یا نشست منقضی شده است.')));}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('داشبورد دانش‌آموز'),actions:[IconButton(onPressed:logout,tooltip:'خروج',icon:const Icon(Icons.logout))]),body:RefreshIndicator(onRefresh:load,child:loading?const ListView(children:[SizedBox(height:280),Center(child:CircularProgressIndicator())]):error!=null?ListView(padding:const EdgeInsets.all(24),children:[Text(error!),FilledButton(onPressed:load,child:const Text('تلاش دوباره'))]):ListView(padding:const EdgeInsets.all(16),children:[Text(data!.profile.fullName,