class ExamPage extends StatefulWidget { const ExamPage({super.key,required this.api,required this.token,required this.attemptId,required this.title}); final StudentApi api; final String token,attemptId,title; @override State<ExamPage> createState()=>_ExamPageState(); }
class _ExamPageState extends State<ExamPage>{List<ExamQuestion> questions=[];Map<int,int> answers={};int index=0;bool loading=true,saving=false;String? error;Duration? remaining;Timer? timer;@override void initState(){super.initState();load();}@override void dispose(){timer?.cancel();super.dispose();}Future<void> load()async{try{final state=await widget.api.attemptState(widget.attemptId,widget.token);final qs=await widget.api.questions(widget.attemptId,widget.token);if(!mounted)return;setState((){answers=Map.of(state.answers);questions=qs;loading=false;});if(state.deadlineAt!=null&&state.serverNow!=null){remaining=state.deadlineAt!.difference(state.serverNow!);timer=Timer.periodic(const Duration(seconds:1),(_){if(!mounted)return;setState(()=>remaining=Duration(seconds:(remaining!.inSeconds-1).clamp(0,1<<31)));if(remaining!.inSeconds==0)submit();});}}catch(_){if(mounted)setState((){error='دریافت سؤال‌ها انجام نشد.';loading=false;});}}Future<void> choose(ExamQuestion q,int optionId)async{setState(()=>saving=true);try{await widget.api.saveAnswer(widget.attemptId,q.id,optionId,widget.token);if(mounted)setState(()=>answers[q.id]=optionId);}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ذخیره پاسخ انجام نشد؛ دوباره تلاش کنید.')));}finally{if(mounted)setState(()=>saving=false);}}Future<void> submit()async{final ok=remaining?.inSeconds==0?true:await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('ثبت نهایی آزمون'),content:const Text('پس از ثبت نهایی امکان تغییر پاسخ‌ها وجود ندارد.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('انصراف')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('ثبت نهایی'))]))??false;if(!ok||!mounted)return;try{final result=await widget.api.submit(widget.attemptId,widget.token);if(!mounted)return;Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>ResultPage(api:widget.api,token:widget.token,attemptId:result.attemptId,initial:result)));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ثبت نهایی انجام نشد.')));}}@override Widget build(BuildContext context){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(error!=null)return Scaffold(appBar:AppBar(),body:Center(child:Text(error!)));if(questions.isEmpty)return const Scaffold(body:Center(child:Text('سؤالی برای این آزمون یافت نشد.')));final q=questions[index];return Scaffold(appBar:AppBar(title:Text(widget.title),actions:[if(remaining!=null)Padding(padding:const EdgeInsets.all(16),child:Center(child:Text('${remaining!.inMinutes}:${(remaining!.inSeconds%60).toString().padLeft(2,'0')}')))]),body:ListView(padding:const EdgeInsets.all(16),children:[LinearProgressIndicator(value:(index+1)/questions.length),const SizedBox(height:16),Text('سؤال ${q.order} از ${questions.length}',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:12),Text(q.text,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:16),...q.options.map((o)=>RadioListTile<int>(value:o.id,groupValue:answers[q.id],onChanged:saving?null:(v){if(v!=null)choose(q,v);},title:Text('${o.key}) ${o.text}'))),const SizedBox(height:12),Row(children:[OutlinedButton(onPressed:index>0?()=>setState(()=>index--):null,child:const Text('قبلی')),const Spacer(),if(index<questions.length-1)FilledButton(onPressed:()=>setState(()=>index++),child:const Text('بعدی'))else FilledButton(onPressed:submit,child:const Text('ثبت نهایی'))])])) ;}}

