class _ResultPageState extends State<ResultPage>{StudentResult? result;String? error;@override void initState(){super.initState();result=widget.initial;if(result==null)load();}Future<void> load()async{try{final r=await widget.api.result(widget.attemptId,widget.token);if(mounted)setState(()=>result=r);}catch(_){if(mounted)setState(()=>error='کارنامه در دسترس نیست.');}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('کارنامه آزمون')),body:result==null?Center(child:error==null?const CircularProgressIndicator():Text(error!)):Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:520),child:Card(margin:const EdgeInsets.all(20),child:Padding(padding:const EdgeInsets.all(24),child:result!.resultVisible?Column(mainAxisSize:MainAxisSize.min,children:[Text(result!.examTitle,style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:20),Text('${result!.percentage?.toStringAsFixed(1)??'—'}٪',style:Theme.of(context).textTheme.displaySmall),const SizedBox(height:16),Wrap(spacing:16,children:[Text('صحیح: ${result!.correctCount??'—'}'),Text('غلط: ${result!.wrongCount??'—'}'),Text('نزده: ${result!.blankCount??'—'}')]),if(!result!.detailVisible)...[const SizedBox(height:16),const Text('جزئیات پاسخ‌ها پس از بسته‌شدن آزمون نمایش داده می‌شود.')]]):const Text('نتیجه این آزمون هنوز برای دانش‌آموز منتشر نشده است.')))))));
